# ---- level-language section (SL), our words
LEVELS = ['entry-1', 'entry-2', 'entry-3', 'l1', 'l2', 'l3', 'l4', 'l5', 'l6', 'l7', 'l8']
DEFINING = {  # what makes each level itself: our words; practitioner, student
 'entry-1': ('Progress at the very start: from the most basic achievement to beginning to use skills and knowledge tied to one\'s immediate surroundings.', 'At Entry 1, you are taking first steps: starting to use skills and knowledge in the world right around you.'),
 'entry-2': ('Simple, familiar tasks done with guidance, by following instructions or practised steps.', 'At Entry 2, you do simple things you know, with help, by following instructions or steps you have practised.'),
 'entry-3': ('Structured tasks in familiar settings, with guidance where needed; first awareness that actions have consequences.', 'At Entry 3, you do structured tasks in situations you know, with help when needed, and you see that what you do affects others.'),
 'l1': ('Routine, clearly defined tasks completed using relevant knowledge and procedures, under direction; checking whether actions worked.', 'At Level 1, you finish routine tasks with clear instructions, using what you know, and check whether it worked.'),
 'l2': ('Defined tasks and straightforward problems, with chosen skills and gathered information; some autonomy within overall direction.', 'At Level 2, you solve simple problems as well as set tasks, choosing your own methods and making some of your own decisions.'),
 'l3': ('Defined problems that may be complex and non-routine; theory enters; initiating tasks and guiding others; aware of different perspectives; autonomy within limited parameters.', 'At Level 3, problems can be complex and new to you; you use theory, start tasks yourself, may guide others and know your field holds different views.'),
 'l4': ('Complex, non-routine problems that are still fairly well defined; analysis joins interpretation and evaluation; adapting methods; initiating investigation; responsible for courses of action; informed awareness of perspectives; broad but defined parameters.', 'At Level 4, you analyse as well as interpret, adapt methods, start your own investigations and take responsibility for a whole course of action.'),
 'l5': ('Complex problems that are only broadly defined; finding ways forward; deciding on methods; using research; planning and developing courses of action; understanding schools of thought and their reasoning.', 'At Level 5, problems are loosely defined; you find a way forward, decide on methods, use research and understand why different schools of thought hold.'),
 'l6': ('Problems of limited definition with many interacting factors; refining understanding to create ways forward; critical analysis; designing research; courses of action that can underpin substantial change; broad autonomy.', 'At Level 6, you work on loosely defined problems where many things interact, think critically, design research and lead work that can support big change.'),
 'l7': ('Problematic situations conceptualised; understanding reformulated; modified conceptions produced; methodologies determined; research or strategy designed to change practice; critical evaluation of long-term implications; autonomy across a significant area.', 'At Level 7, you frame difficult situations yourself, rework ideas into new ones, choose whole research approaches and lead change across a large area.'),
 'l8': ('Original understanding where nothing is defined; new knowledge and theory; formulating methodologies; extending the field; leadership as a leading practitioner or scholar; advancing professional practice.', 'At Level 8, you create new knowledge and research approaches of your own, push your field forward and lead it as a recognised expert.'),
}
